import test from 'node:test';
import assert from 'node:assert/strict';
import { rotate } from '../src/rotate.js';

const cases = [
  { name: 'one step', original: [1, 2, 3, 4], k: 1, expected: [4, 1, 2, 3] },
  { name: 'two steps', original: [1, 2, 3, 4], k: 2, expected: [3, 4, 1, 2] },
  { name: 'three steps', original: [1, 2, 3, 4], k: 3, expected: [2, 3, 4, 1] },
  { name: 'full rotation', original: [1, 2, 3, 4], k: 4, expected: [1, 2, 3, 4] },
  { name: 'steps exceeding length', original: [1, 2, 3, 4], k: 6, expected: [3, 4, 1, 2] },
  { name: 'duplicates retain order', original: ['a', 'b', 'a', 'c'], k: 1, expected: ['c', 'a', 'b', 'a'] },
  { name: 'zero steps', original: [1, 2, 3, 4], k: 0, expected: [1, 2, 3, 4] },
  { name: 'empty array with zero steps', original: [], k: 0, expected: [] },
  { name: 'empty array with positive steps', original: [], k: 6, expected: [] },
  { name: 'singleton with zero steps', original: [7], k: 0, expected: [7] },
  { name: 'singleton with positive steps', original: [7], k: 6, expected: [7] },
  { name: 'frozen array', original: [1, 2, 3, 4], k: 1, expected: [4, 1, 2, 3], frozen: true },
];

for (const { name, original, k, expected, frozen } of cases) {
  test(`rotate: ${name}`, () => {
    const input = [...original];
    if (frozen) Object.freeze(input);

    const result = rotate(input, k);

    assert.ok(Array.isArray(result));
    assert.notStrictEqual(result, input, 'must return a new array');
    assert.deepStrictEqual(result, expected);
    assert.deepStrictEqual(input, original, 'must preserve input contents');
  });
}

const nonArrays = [
  { name: 'null', value: null },
  { name: 'undefined', value: undefined },
  { name: 'number', value: 42 },
  { name: 'string', value: 'abcd' },
  { name: 'plain object', value: {} },
  { name: 'array-like object', value: { 0: 'a', 1: 'b', length: 2 } },
];

for (const { name, value } of nonArrays) {
  test(`rotate rejects ${name} with TypeError`, () => {
    assert.throws(() => rotate(value, 1), TypeError);
  });
}

for (const k of [-1, -4, 0.5, 1.5, -0.5, -1.5]) {
  test(`rotate rejects invalid steps ${k} on a nonempty array`, () => {
    const input = [1, 2, 3, 4];
    assert.throws(() => rotate(input, k), RangeError);
    assert.deepStrictEqual(input, [1, 2, 3, 4]);
  });

  test(`rotate rejects invalid steps ${k} on an empty array`, () => {
    const input = [];
    assert.throws(() => rotate(input, k), RangeError);
    assert.deepStrictEqual(input, []);
  });
}

